export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
  previousContracts: number;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / 100;
}

function itemPremium(item: Item): number {
  const base = BASE_PREMIUMS[item.type];
  const curseSurcharge = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
  return base + curseSurcharge;
}

export function quote(items: Item[], _customer: Customer): number {
  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const itemPremiums = items.reduce((sum, item) => sum + itemPremium(item), 0);
  return itemPremiums + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
}
EOF
