import { Item } from './premium';

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

export class Policy {
  private remainingCap: number;

  constructor(items: Item[]) {
    this.remainingCap = CAP_FACTOR * items.length * 1000;
  }

  claim(damages: Damage[]): ClaimResult {
    const payout = damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}
EOF
