import { Item, priceListEntry } from './catalog';

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

function reimbursementRate(item: Item): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : 1;
}

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = CAP_FACTOR * items.reduce((sum, item) => sum + priceListEntry(item.type).insuranceValue, 0);
  }

  claim(damages: Damage[]): ClaimResult {
    const payout = damages.reduce((sum, damage) => sum + this.damagePayout(damage), 0);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }

  private damagePayout(damage: Damage): number {
    const item = this.items.find((candidate) => candidate.type === damage.itemType) as Item;
    return damage.amount * reimbursementRate(item) - DEDUCTIBLE;
  }
}
